## Background: a regression that must be fixed

`src/view/shell.html` used to have an inline `<script>` implementing: a live text filter over matrix rows, click-to-sort table headers, an accordion expand/collapse toggle for force detail rows, and a fusion/fission-candidate highlighter driven by a threshold slider. That inline script was just deleted wholesale as part of wiring in the new TS-based live-editing system (Phases 0-8 of `/home/v0id/Documents/repos/residual/residual/iterations/view-live-editing-plan.md`), and NONE of that functionality was reimplemented anywhere — it's a real regression. Your job is to write tests for a new module, `web/src/matrix-view.ts`, that restores this behavior faithfully, so it can be wired into `web/src/main.ts` (not your job — someone else does that after green).

## The exact original logic (preserve this behavior faithfully — read this carefully, it's the spec)

```js
// Filter: hide/show tr.force-row by substring match against data-search
const filterInput = document.querySelector("[data-force-filter]");
filterInput.addEventListener("input", () => {
  const q = filterInput.value.trim().toLowerCase();
  document.querySelectorAll("table.matrix tbody tr.force-row").forEach((row) => {
    const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
    row.hidden = q !== "" && hay.indexOf(q) === -1;
  });
});

// Accordion: toggle aria-expanded + sibling .force-detail's hidden
document.querySelectorAll("[data-accordion-toggle]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const detail = btn.nextElementSibling;
    if (!detail) return;
    const expanded = btn.getAttribute("aria-expanded") === "true";
    btn.setAttribute("aria-expanded", String(!expanded));
    detail.hidden = expanded;
  });
});

// Sort: click th[data-sort-key] reorders tbody rows; toggles asc/desc, exclusive across headers
function sortMatrixBy(key, dir) {
  const table = document.querySelector("table.matrix");
  const tbody = table && table.querySelector("tbody");
  if (!tbody) return;
  const rows = Array.from(tbody.querySelectorAll("tr.force-row"));
  const mult = dir === "desc" ? -1 : 1;
  rows.sort((ra, rb) => {
    if (key === "force") {
      return (ra.getAttribute("data-force-id") || "").localeCompare(rb.getAttribute("data-force-id") || "") * mult;
    }
    if (key === "total") {
      return (Number(ra.getAttribute("data-row-total") || 0) - Number(rb.getAttribute("data-row-total") || 0)) * mult;
    }
    if (key.indexOf("component:") === 0) {
      const comp = key.slice("component:".length);
      const ca = ra.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
      const cb = rb.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
      const va = ca && ca.getAttribute("data-coupled") === "1" ? 1 : 0;
      const vb = cb && cb.getAttribute("data-coupled") === "1" ? 1 : 0;
      return (va - vb) * mult;
    }
    return 0;
  });
  rows.forEach((row) => tbody.appendChild(row));
}
document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((th) => {
  const activate = () => {
    const key = th.getAttribute("data-sort-key");
    const current = th.classList.contains("sort-asc") ? "asc" : th.classList.contains("sort-desc") ? "desc" : null;
    const next = current === "asc" ? "desc" : "asc";
    document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((other) => other.classList.remove("sort-asc", "sort-desc"));
    th.classList.add(next === "asc" ? "sort-asc" : "sort-desc");
    sortMatrixBy(key, next);
  };
  th.addEventListener("click", activate);
  th.addEventListener("keydown", (ev) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); activate(); } });
});

// Fusion/fission: components with identical coupling vectors across all forces -> fusion candidates;
// components whose column total exceeds the threshold -> fission candidates. Driven by a threshold
// slider (auto-initialized to floor(numForces/2), min 1) and an optional "only show candidates" filter.
function computeMatrixCandidates() {
  const table = document.querySelector("table.matrix");
  const fusion = new Set(); const fission = new Set();
  if (!table) return { fusion, fission };
  const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) => th.getAttribute("data-component"));
  const vectors = {};
  componentNames.forEach((name) => { vectors[name] = {}; });
  table.querySelectorAll("tbody td[data-residue-cell]").forEach((td) => {
    const comp = td.getAttribute("data-component"); const force = td.getAttribute("data-force-id");
    if (vectors[comp]) vectors[comp][force] = td.getAttribute("data-coupled") === "1";
  });
  for (let i = 0; i < componentNames.length; i++) {
    for (let j = i + 1; j < componentNames.length; j++) {
      const a = vectors[componentNames[i]]; const b = vectors[componentNames[j]];
      const forceIds = Object.keys(a);
      const identical = forceIds.length > 0 && forceIds.every((fid) => a[fid] === b[fid]);
      if (identical) { fusion.add(componentNames[i]); fusion.add(componentNames[j]); }
    }
  }
  const thresholdInput = document.querySelector("[data-threshold-input]");
  const threshold = thresholdInput ? Number(thresholdInput.value) : 1;
  table.querySelectorAll("tfoot td[data-col-total]").forEach((td) => {
    const total = Number(td.getAttribute("data-col-total"));
    if (total > threshold) fission.add(td.getAttribute("data-component"));
  });
  return { fusion, fission };
}
function applyFusionFissionHighlighting() {
  const table = document.querySelector("table.matrix");
  if (!table) return;
  const { fusion, fission } = computeMatrixCandidates();
  const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) => th.getAttribute("data-component"));
  const onlyToggle = document.querySelector("[data-fusion-fission-filter]");
  const only = !!(onlyToggle && onlyToggle.checked);
  componentNames.forEach((name) => {
    const isFusion = fusion.has(name); const isFission = fission.has(name);
    const show = !only || isFusion || isFission;
    table.querySelectorAll('[data-component="' + CSS.escape(name) + '"]').forEach((el) => {
      el.setAttribute("data-fusion", isFusion ? "1" : "0");
      el.setAttribute("data-fission", isFission ? "1" : "0");
      el.hidden = !show;
    });
  });
}
// On init: thresholdInput.min="1", max=max(1,numForces), value=max(1,floor(numForces/2)), output text synced;
// re-run applyFusionFissionHighlighting on threshold input and on the "only candidates" checkbox's change event.
```

Note: this logic operated against a STATIC server-rendered table (no live edits). It now needs to also stay correct as rows/columns are added dynamically by the live-editing system (`matrix-interactions.ts`, `forms.ts` — already built, stable, not your concern to modify) — so design your `mount`-style entry point to be RE-INVOKABLE (callable again after a DOM mutation to recompute fusion/fission and reapply filter/sort state) rather than only wiring one-time event listeners that go stale. Read `web/src/matrix-interactions.ts`'s and `web/src/forms.ts`'s header comments for their `MountOptions.onChange`/`{ onChange }` pattern — your module should fit the same pattern so `main.ts` can call your recompute function from the same shared `onChange` callback everything else already uses.

## What to build: `web/src/matrix-view.ts` + colocated `.test.ts`

Design (your call on exact shape, but cover all of this):

```ts
export interface MatrixViewOptions { /* whatever you need, e.g. no options at all */ }
export interface MatrixViewHandle {
  recomputeFusionFission(): void; // callable again after external DOM mutations (new rows/columns)
}
export function mountMatrixView(container: HTMLElement, options?: MatrixViewOptions): MatrixViewHandle
```

Test, using real DOM interactions (dispatch real events), against a fixture mirroring the matrix markup contract (same shape used in `matrix-interactions.test.ts` — reuse/adapt that fixture-building style):

1. Filter: typing into `[data-force-filter]` hides rows whose `data-search` doesn't match (case-insensitive substring), clearing the input un-hides all.
2. Accordion: clicking a `[data-accordion-toggle]` button flips `aria-expanded` and its sibling `.force-detail`'s `hidden` attribute; clicking again reverses it.
3. Sort: clicking a `th[data-sort-key="force"]` reorders `tbody` rows ascending by `data-force-id` first click, descending second click (exclusive — clicking a different header clears the first header's sort class); test `th[data-sort-key="total"]` sorts by `data-row-total` numerically; test a `data-sort-key="component:<name>"` header sorts by that column's `data-coupled` value. Test keyboard activation (`Enter`/`Space` on a focused header) does the same as a click.
4. Fusion/fission: two components with byte-identical coupling vectors across all forces both get `data-fusion="1"` set on every element sharing their `data-component` attribute (header, cells, footer total) after `recomputeFusionFission()` runs; a component whose footer `data-col-total` exceeds the current `[data-threshold-input]` value gets `data-fission="1"`; the `[data-fusion-fission-filter]` checkbox, when checked, hides (`hidden = true`) every element for a component that's neither a fusion nor fission candidate, and un-hides them when unchecked. Test threshold auto-initialization: for N force rows in the fixture, `[data-threshold-input]`'s `min` becomes `"1"`, `max` becomes `String(N)`, `value` becomes `String(Math.max(1, Math.floor(N/2)))`, and `[data-threshold-value]`'s text content matches. Test that moving the threshold slider (dispatch an `input` event with a new `.value`) recomputes and reapplies fission highlighting live.
5. Re-invocation: call `mountMatrixView` once, then simulate an externally-added row/column (append DOM nodes directly in the test, mimicking what `matrix-interactions.ts`/`forms.ts` would do), then call the handle's `recomputeFusionFission()` and assert the new elements get correctly marked — this is the test proving the "stays correct after live edits" requirement.

## Constraints

- Real DOM APIs only, no `innerHTML` with interpolated untrusted content.
- Strict TS, no `any`.
- Don't modify `matrix-interactions.ts`, `forms.ts`, `model.ts`, or any other existing stable module/test file.
- Stub function(s) throw `new Error("not yet implemented — green phase")`.

## Verify before finishing

Run `cd web && nix develop /home/v0id/Documents/repos/residual -c bun test` and confirm the 169 pre-existing tests still pass unchanged, and your new tests fail via the intended stub throw. Report: files created, the `mountMatrixView`/`MatrixViewHandle` signatures you settled on, test names, and the `bun test` tail output. Keep prose under 450 words plus signatures/output.

